import { PivotGrid, type PivotField } from '@absoluteui/components/pivot-grid';

interface Sale {
  region: string;
  city: string;
  date: string;
  amount: number;
}

const sales: Sale[] = [
  { region: 'North', city: 'Oslo', date: '2026-01-15', amount: 1200 },
  { region: 'North', city: 'Bergen', date: '2026-04-02', amount: 800 },
  { region: 'South', city: 'Rome', date: '2026-02-20', amount: 1500 },
];

const fields: PivotField<Sale>[] = [
  { id: 'region', label: 'Region' },
  { id: 'city', label: 'City' },
  // Group dates by quarter in the accessor (the key is text such as 'Q1').
  { id: 'quarter', label: 'Quarter', value: (s) => `Q${String(Math.ceil(Number(s.date.slice(5, 7)) / 3))}` },
  { id: 'amount', label: 'Amount', numberFormat: { style: 'currency', currency: 'EUR' } },
];

const host = document.createElement('div');
document.body.append(host);
const grid = PivotGrid.create(host, {
  caption: 'Sales 2026',
  fields,
  data: sales,
  layout: { rows: ['region', 'city'], columns: ['quarter'], values: [{ field: 'amount', aggregate: 'sum' }] },
});
void grid.ready.then(() => {
  host.dataset.total = String(grid.toMatrix().values.at(-1)?.at(-1) ?? '');
});

import { PivotGrid, type PivotDataSource, type PivotGridLoadErrorDetail, type PivotMembersResult, type PivotQueryResult } from '@absoluteui/components/pivot-grid';

// The server answers the query contract: one cell per requested (row path, column path) with records.
// The grid validates every answer before it renders it.
const source: PivotDataSource = {
  query: async (query, signal) => {
    const response = await fetch('/api/pivot/query', { method: 'POST', body: JSON.stringify(query), headers: { 'content-type': 'application/json' }, signal });
    if (!response.ok) throw new Error(`Pivot query failed: ${String(response.status)}`);
    return (await response.json()) as PivotQueryResult;
  },
  members: async (request, signal) => {
    const response = await fetch('/api/pivot/members', { method: 'POST', body: JSON.stringify(request), headers: { 'content-type': 'application/json' }, signal });
    if (!response.ok) throw new Error(`Pivot members failed: ${String(response.status)}`);
    return (await response.json()) as PivotMembersResult;
  },
};

const host = document.querySelector<HTMLElement>('#orders-pivot');
if (host) {
  PivotGrid.create(host, {
    caption: 'Orders',
    fields: [{ id: 'country', label: 'Country' }, { id: 'customer', label: 'Customer' }, { id: 'year', label: 'Year' }, { id: 'total', label: 'Total' }],
    dataSource: source,
    // Only the top level loads first; each group loads when it is expanded.
    expandDepth: 0,
    requestTimeoutMs: 15_000,
    virtual: true,
    layout: { rows: ['country', 'customer'], columns: ['year'], values: [{ field: 'total', aggregate: 'sum' }] },
  });
  host.addEventListener('aui-load-error', (event) => {
    const { request } = (event as CustomEvent<PivotGridLoadErrorDetail>).detail;
    host.dataset.failed = request;
  });
}

import { PivotFieldList, PivotGrid, type PivotGridLayoutChangeDetail, type PivotLayout } from '@absoluteui/components/pivot-grid';

interface Ticket {
  team: string;
  priority: 'low' | 'high';
  status: string;
  hours: number;
}

const tickets: Ticket[] = [
  { team: 'Core', priority: 'high', status: 'open', hours: 5 },
  { team: 'Web', priority: 'low', status: 'closed', hours: 2 },
];
let saved: PivotLayout | null = null;

const listHost = document.createElement('div');
const gridHost = document.createElement('div');
document.body.append(listHost, gridHost);

const grid = PivotGrid.create(gridHost, {
  caption: 'Tickets',
  fields: [
    { id: 'team', label: 'Team' },
    { id: 'priority', label: 'Priority', formatMember: (key) => (key === 'high' ? 'High' : 'Low') },
    { id: 'status', label: 'Status', areas: ['rows', 'columns', 'filters'] },
    { id: 'hours', label: 'Hours', aggregate: 'average' },
  ],
  data: tickets,
  layout: saved ?? { rows: ['team'], columns: ['priority'], values: [{ field: 'hours', aggregate: 'sum' }] },
});
PivotFieldList.create(listHost, { grid, label: 'Pivot fields' });
gridHost.addEventListener('aui-layout-change', (event) => {
  saved = (event as CustomEvent<PivotGridLayoutChangeDetail>).detail.layout;
});

import { downloadCsv, PivotGrid } from '@absoluteui/components/pivot-grid';
import { BarChart } from '@absoluteui/components/bar-chart';
import { Button } from '@absoluteui/components/button';

const rows = [
  { product: 'A', month: '2026-01', units: 10 },
  { product: 'B', month: '2026-01', units: 4 },
  { product: 'A', month: '2026-02', units: 7 },
];
const host = document.createElement('div');
const chartHost = document.createElement('div');
document.body.append(host, chartHost);
const grid = PivotGrid.create(host, {
  caption: 'Units by product',
  fields: [{ id: 'product', label: 'Product' }, { id: 'month', label: 'Month' }, { id: 'units', label: 'Units' }],
  data: rows,
  grandTotals: 'none',
  layout: { rows: ['product'], columns: ['month'], values: [{ field: 'units', aggregate: 'sum' }] },
});
void grid.ready.then(() => {
  const matrix = grid.toMatrix();
  BarChart.create(chartHost, {
    label: 'Units by product',
    categories: matrix.rows.map((r) => r.labels.join(' / ')),
    series: matrix.columns.map((c, j) => ({ id: `c${String(j)}`, label: c.labels.join(' / '), values: matrix.values.map((row) => row[j] ?? null) })),
  });
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'Download CSV';
Button.enhance(button);
  button.addEventListener('click', () => {
    downloadCsv(grid.toCsv({ bom: true }), 'units.csv');
  });
  host.before(button);
});
